package com.example.techfix.adapters;
import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.LinearLayout;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.core.content.ContextCompat;import androidx.recyclerview.widget.RecyclerView;import com.example.techfix.R;import com.example.techfix.models.Appointment;import com.google.android.material.button.MaterialButton;import java.util.List;
public class AppointmentAdapter extends RecyclerView.Adapter<AppointmentAdapter.ViewHolder>{public interface OnAppointmentActionListener{void onActionClick(Appointment appointment);}private List<Appointment> appointments;private boolean isAdmin;private OnAppointmentActionListener actionListener;public AppointmentAdapter(List<Appointment> a,boolean admin,OnAppointmentActionListener l){appointments=a;isAdmin=admin;actionListener=l;}@NonNull public ViewHolder onCreateViewHolder(@NonNull ViewGroup p,int t){return new ViewHolder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_appointment,p,false));}public void onBindViewHolder(@NonNull ViewHolder h,int pos){Appointment a=appointments.get(pos);h.tvDeviceCategory.setText(a.getDeviceCategory()+" Repair");h.tvAppId.setText("#"+a.getId());h.tvAssignedBranch.setText(a.getBranchName()+"\nTechnician: "+(a.getTechnicianName()==null?"Not yet assigned":a.getTechnicianName())+(a.getAssignmentNote()==null||a.getAssignmentNote().isEmpty()?"":"\n"+a.getAssignmentNote()));h.tvIssueDescription.setText(a.getIssueDescription()==null?"No issue description":a.getIssueDescription());String s=a.getStatus();h.tvStatusBadge.setText(s.toUpperCase());h.tvStatusBadge.setBackgroundResource("Pending".equalsIgnoreCase(s)?R.drawable.status_badge_pending:("In Progress".equalsIgnoreCase(s)?R.drawable.status_badge_inprogress:R.drawable.status_badge_completed));h.tvCustomerName.setVisibility(View.VISIBLE);h.tvCustomerName.setText(a.getUserName()==null?"Local customer":a.getUserName());h.btnActionButton.setOnClickListener(v->{if(actionListener!=null)actionListener.onActionClick(a);});if(isAdmin){if("Pending".equalsIgnoreCase(s)){showAction(h,"Start Repair");}else if("In Progress".equalsIgnoreCase(s)){showAction(h,"Complete Repair");}else{h.layoutActionButtons.setVisibility(View.GONE);}}else if("Completed".equalsIgnoreCase(s)){showAction(h,"Pay Now (Simulated)");}else if("Paid".equalsIgnoreCase(s)){showAction(h,"Receipt / Paid");h.btnActionButton.setEnabled(false);}else h.layoutActionButtons.setVisibility(View.GONE);}private void showAction(ViewHolder h,String label){h.layoutActionButtons.setVisibility(View.VISIBLE);h.btnActionButton.setVisibility(View.VISIBLE);h.btnActionButton.setEnabled(true);h.btnActionButton.setText(label);h.btnActionButton.setBackgroundColor(ContextCompat.getColor(h.itemView.getContext(),R.color.tech_accent));}public int getItemCount(){return appointments.size();}public void updateList(List<Appointment> l){appointments=l;notifyDataSetChanged();}static class ViewHolder extends RecyclerView.ViewHolder{TextView tvDeviceCategory,tvAppId,tvCustomerName,tvAssignedBranch,tvStatusBadge,tvIssueDescription;LinearLayout layoutActionButtons;MaterialButton btnActionButton;ViewHolder(View v){super(v);tvDeviceCategory=v.findViewById(R.id.tvDeviceCategory);tvAppId=v.findViewById(R.id.tvAppId);tvCustomerName=v.findViewById(R.id.tvCustomerName);tvAssignedBranch=v.findViewById(R.id.tvAssignedBranch);tvStatusBadge=v.findViewById(R.id.tvStatusBadge);tvIssueDescription=v.findViewById(R.id.tvIssueDescription);layoutActionButtons=v.findViewById(R.id.layoutActionButtons);btnActionButton=v.findViewById(R.id.btnActionButton);}}}